1	{
2	  "name": "stockroom",
3	  "version": "0.0.0",
4	  "private": true,
5	  "type": "module",
6	  "engines": {
7	    "node": ">=24 <25"
8	  },
9	  "scripts": {
10	    "start": "node app.ts"
11	  },
12	  "bin": {
13	    "stockroom": "app.ts"
14	  }
15	}
16

1	#!/usr/bin/env node
2	// stockroom —— 本地多仓库存台账（Node.js 24，TypeScript，无外部运行依赖）
3	
4	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
5	import { join } from 'node:path';
6	
7	const APP_NAME = 'stockroom';
8	const DATA_FILENAME = 'stockroom.json';
9	const DEFAULT_DATA_DIR = '.stockroom';
10	
11	class UsageError extends Error {} // 命令行用法错误 -> 退出码 2
12	class BizError extends Error {} // 业务拒绝 -> 退出码 1
13	class DataError extends Error {} // 数据读取/保存失败 -> 退出码 1
14	
15	type DocType = 'in' | 'out' | 'transfer';
16	type EntryType =
17	  | DocType
18	  | 'count'
19	  | 'arrival'
20	  | 'in-rev'
21	  | 'out-rev'
22	  | 'transfer-rev'
23	  | 'count-rev'
24	  | 'arrival-rev';
25	
26	interface LedgerEntry {
27	  seq: number; // 全局流水序号，即提交顺序
28	  doc: string; // 单据编号（冲销流水此处为冲销单编号）
29	  type: EntryType;
30	  product: string;
31	  wh: string; // 本流水条目变动余量的仓库（到货为采购单收货仓）
32	  qty?: number; // 入库/出库/调拨/到货类流水：恒为正数，方向由类型 / 出入仓决定；盘点类流水不用此字段
33	  before: number;
34	  after: number;
35	  from?: string; // 调拨（或冲销调拨）的调出仓
36	  to?: string; // 调拨（或冲销调拨）的调入仓
37	  po?: string; // 到货流水：所属采购单编号
38	  orig?: string; // 冲销流水：被冲销的原单编号
39	  expected?: number; // 盘点（及冲销盘点）流水：预期账面量
40	  actual?: number; // 盘点（及冲销盘点）流水：实盘量
41	  diff?: number; // 盘点差额 = 实盘 - 账面（可正、可负、可零）；冲销盘点流水记录原差额
42	}
43	
44	interface DocRecord {
45	  content: Record<string, unknown>; // 规范化业务内容（明细顺序无关）
46	  resultLines: string[]; // 原提交结果，供幂等重放
47	}
48	
49	interface ReversalRecord {
50	  orig: string; // 被冲销的原单编号
51	  resultLines: string[]; // 冲销提交结果，供幂等重放
52	}
53	
54	interface PurchaseRecord {
55	  poId: string;
56	  supplier: string;
57	  wh: string; // 收货仓
58	  ordered: Record<string, number>; // 商品 -> 订购量（合并后，正安全整数）
59	  resultLines: string[]; // 登记结果，供幂等重放
60	}
61	
62	interface ArrivalRecord {
63	  poId: string; // 所属采购单
64	  wh: string; // 采购单收货仓（冗余自采购单，便于校验与展示）
65	  qty: Record<string, number>; // 本次到货：商品 -> 数量（合并后，正安全整数）
66	  resultLines: string[]; // 到货提交结果，供幂等重放
67	}
68	
69	interface Store {
70	  version: 1;
71	  products: Record<string, string>; // 编号 -> 名称（编号区分大小写；null 原型，防特殊键串改）
72	  stock: Record<string, Record<string, number>>; // 商品 -> 仓库 -> 余量
73	  entries: LedgerEntry[];
74	  docs: Record<string, DocRecord>; // 入库/出库/调拨/盘点单去重与结果
75	  reversals: Record<string, ReversalRecord>; // 冲销单去重与结果（可冲销到货单）
76	  purchases: Record<string, PurchaseRecord>; // 采购单登记（独立编号空间，不改库存）
77	  arrivals: Record<string, ArrivalRecord>; // 到货单去重与结果（与库存单共用编号空间）
78	}
79	
80	const REV_ENTRY_TYPES = new Set<EntryType>(['in-rev', 'out-rev', 'transfer-rev', 'count-rev', 'arrival-rev']);
81	
82	function nullProto<T extends object>(): T {
83	  return Object.create(null) as T;
84	}
85	
86	function emptyStore(): Store {
87	  return {
88	    version: 1,
89	    products: nullProto(),
90	    stock: nullProto(),
91	    entries: [],
92	    docs: nullProto(),
93	    reversals: nullProto(),
94	    purchases: nullProto(),
95	    arrivals: nullProto(),
96	  };
97	}
98	
99	// ---------- 工具 ----------
100	
101	function isPlainObject(v: unknown): v is Record<string, unknown> {
102	  return typeof v === 'object' && v !== null && !Array.isArray(v);
103	}
104	
105	function isNonNegSafeInt(v: unknown): v is number {
106	  return typeof v === 'number' && Number.isSafeInteger(v) && v >= 0;
107	}
108	
109	function isPosSafeInt(v: unknown): v is number {
110	  return typeof v === 'number' && Number.isSafeInteger(v) && v > 0;
111	}
112	
113	function trimOrThrow(label: string, raw: string): string {
114	  const s = raw.trim();
115	  if (s === '') throw new BizError(`${label}去除首尾空白后不能为空`);
116	  return s;
117	}
118	
119	/** 规范化序列化：对象键排序，保证业务内容比较与明细顺序无关。 */
120	function stableStringify(v: unknown): string {
121	  if (isPlainObject(v)) {
122	    return (
123	      '{' +
124	      Object.keys(v)
125	        .sort()
126	        .map((k) => JSON.stringify(k) + ':' + stableStringify(v[k]))
127	        .join(',') +
128	      '}'
129	    );
130	  }
131	  if (Array.isArray(v)) return '[' + v.map(stableStringify).join(',') + ']';
132	  return JSON.stringify(v);
133	}
134	
135	// ---------- 数据持久化 ----------
136	
137	function dataPath(dataDir: string): string {
138	  return join(dataDir, DATA_FILENAME);
139	}
140	
141	function loadStore(dataDir: string): Store {
142	  let raw: string;
143	  try {
144	    raw = readFileSync(dataPath(dataDir), 'utf8');
145	  } catch (e) {
146	    if ((e as NodeJS.ErrnoException).code === 'ENOENT') return emptyStore(); // 尚不存在 -> 空库
147	    throw new DataError(`无法读取数据文件 ${dataPath(dataDir)}：${(e as Error).message}`);
148	  }
149	
150	  let data: unknown;
151	  try {
152	    // JSON.parse 将 "__proto__" 保留为普通自有属性（不设置原型）；随后 validateStore
153	    // 会把全部容器重新装入 null 原型对象，constructor 等特殊键同样安全。
154	    data = JSON.parse(raw);
155	  } catch {
156	    throw new DataError(`数据文件已损坏，无法解析 JSON：${dataPath(dataDir)}（不会作为空库覆盖）`);
157	  }
158	  return validateStore(data);
159	}
160	
161	function validateStore(data: unknown): Store {
162	  const bad = (msg: string): DataError =>
163	    new DataError(`数据文件已损坏或格式不正确（${msg}），拒绝启动以免覆盖原数据`);
164	
165	  if (!isPlainObject(data)) throw bad('根节点不是对象');
166	  if (data.version !== 1) throw bad(`不支持的数据版本：${String(data.version)}`);
167	
168	  // 重新装入 null 原型容器：即使磁盘数据来自普通对象，constructor/__proto__ 等键也安全
169	  const store = emptyStore();
170	
171	  if (!isPlainObject(data.products)) throw bad('products 不是对象');
172	  for (const [id, name] of Object.entries(data.products)) {
173	    if (typeof id !== 'string' || id.trim() === '' || typeof name !== 'string')
174	      throw bad('products 中存在非法编号或名称');
175	    store.products[id] = name;
176	  }
177	
178	  if (!isPlainObject(data.stock)) throw bad('stock 不是对象');
179	  for (const [pid, whs] of Object.entries(data.stock)) {
180	    if (!isPlainObject(whs)) throw bad(`商品 ${pid} 的库存不是对象`);
181	    const whMap = nullProto<Record<string, number>>();
182	    for (const [wh, qty] of Object.entries(whs)) {
183	      if (typeof wh !== 'string' || wh.trim() === '' || !isNonNegSafeInt(qty))
184	        throw bad(`商品 ${pid} 仓库 ${String(wh)} 的余量非法`);
185	      whMap[wh] = qty;
186	    }
187	    store.stock[pid] = whMap;
188	  }
189	
190	  if (!Array.isArray(data.entries)) throw bad('entries 不是数组');
191	  let lastSeq = 0;
192	  for (const e of data.entries as unknown[]) {
193	    if (!isPlainObject(e)) throw bad('存在非法流水条目');
194	    if (!isPosSafeInt(e.seq) || e.seq !== ++lastSeq) throw bad('流水序号不连续');
195	    if (typeof e.doc !== 'string' || e.doc.trim() === '') throw bad('流水缺少单据编号');
196	    const isRev = REV_ENTRY_TYPES.has(e.type as EntryType);
197	    const isOrig =
198	      e.type === 'in' || e.type === 'out' || e.type === 'transfer' || e.type === 'count' || e.type === 'arrival';
199	    if (!isRev && !isOrig) throw bad('流水类型非法');
200	    if (typeof e.product !== 'string' || e.product.trim() === '') throw bad('流水缺少商品编号');
201	    if (typeof e.wh !== 'string' || e.wh.trim() === '') throw bad('流水缺少仓库标识');
202	    if (!isNonNegSafeInt(e.before) || !isNonNegSafeInt(e.after)) throw bad('流水余量非法');
203	    if (e.type === 'count' || e.type === 'count-rev') {
204	      if (!isNonNegSafeInt(e.expected) || !isNonNegSafeInt(e.actual))
205	        throw bad('盘点流水账面/实盘量非法');
206	      if (typeof e.diff !== 'number' || !Number.isSafeInteger(e.diff)) throw bad('盘点流水差额非法');
207	      if (e.diff !== e.actual - e.expected) throw bad('盘点流水差额与账面、实盘量不一致');
208	      const applied = e.type === 'count' ? e.diff : -e.diff; // 冲销盘点应用反向差额
209	      if (e.after - e.before !== applied) throw bad('盘点流水差额与前后余量不一致');
210	      if (e.qty !== undefined || e.from !== undefined || e.to !== undefined || e.po !== undefined)
211	        throw bad('盘点流水不应携带数量、调拨或采购字段');
212	    } else {
213	      if (!isPosSafeInt(e.qty)) throw bad('流水数量非法');
214	      if (e.expected !== undefined || e.actual !== undefined || e.diff !== undefined)
215	        throw bad('非盘点流水不应携带盘点字段');
216	      const delta = e.after - e.before;
217	      if (e.type === 'transfer' || e.type === 'transfer-rev') {
218	        if (typeof e.from !== 'string' || e.from.trim() === '' || typeof e.to !== 'string' || e.to.trim() === '')
219	          throw bad('调拨流水缺少调出/调入仓');
220	        if (e.po !== undefined) throw bad('调拨流水不应携带采购字段');
221	        // 调拨：调入仓增加；冲销调拨：原调入仓扣回、原调出仓补回
222	        const expect = (e.wh === e.to) === (e.type === 'transfer') ? e.qty : -e.qty;
223	        if (delta !== expect) throw bad('流水差额与前后余量不一致');
224	      } else {
225	        if (e.from !== undefined || e.to !== undefined) throw bad('非调拨流水不应携带调拨字段');
226	        // 到货入收货仓为增；冲销到货从收货仓扣回为减
227	        const increases = e.type === 'in' || e.type === 'out-rev' || e.type === 'arrival';
228	        if (delta !== (increases ? e.qty : -e.qty)) throw bad('流水差额与前后余量不一致');
229	        if (e.type === 'arrival' || e.type === 'arrival-rev') {
230	          if (typeof e.po !== 'string' || e.po.trim() === '') throw bad('到货流水缺少采购单编号');
231	        } else if (e.po !== undefined) {
232	          throw bad('非到货流水不应携带采购字段');
233	        }
234	      }
235	    }
236	    if (isRev) {
237	      if (typeof e.orig !== 'string' || e.orig.trim() === '') throw bad('冲销流水缺少原单编号');
238	    } else if (e.orig !== undefined) {
239	      throw bad('原始单据流水不应携带冲销标记');
240	    }
241	    store.entries.push(e as unknown as LedgerEntry);
242	  }
243	
244	  if (!isPlainObject(data.docs)) throw bad('docs 不是对象');
245	  for (const [docId, rec] of Object.entries(data.docs)) {
246	    if (typeof docId !== 'string' || docId.trim() === '') throw bad('存在非法单据编号');
247	    if (!isPlainObject(rec) || !isPlainObject(rec.content) || !Array.isArray(rec.resultLines))
248	      throw bad(`单据 ${docId} 的去重记录非法`);
249	    if (!rec.resultLines.every((l) => typeof l === 'string')) throw bad(`单据 ${docId} 的结果记录非法`);
250	    const c = rec.content;
251	    if (c.type !== 'in' && c.type !== 'out' && c.type !== 'transfer' && c.type !== 'count')
252	      throw bad(`单据 ${docId} 的业务类型非法`);
253	    if (!isPlainObject(c.items)) throw bad(`单据 ${docId} 的明细非法`);
254	    for (const [pid, item] of Object.entries(c.items)) {
255	      if (pid.trim() === '') throw bad(`单据 ${docId} 存在非法明细`);
256	      if (c.type === 'count') {
257	        if (!isPlainObject(item) || !isNonNegSafeInt(item.expected) || !isNonNegSafeInt(item.actual))
258	          throw bad(`单据 ${docId} 存在非法盘点明细`);
259	      } else if (!isPosSafeInt(item)) {
260	        throw bad(`单据 ${docId} 存在非法明细`);
261	      }
262	    }
263	    if (c.type === 'transfer') {
264	      if (typeof c.from !== 'string' || c.from.trim() === '' || typeof c.to !== 'string' || c.to.trim() === '')
265	        throw bad(`单据 ${docId} 的调拨仓非法`);
266	    } else if (typeof c.wh !== 'string' || c.wh.trim() === '') {
267	      throw bad(`单据 ${docId} 的仓库非法`);
268	    }
269	    store.docs[docId] = rec as unknown as DocRecord;
270	  }
271	
272	  // purchases 为新增字段：合法旧数据没有该字段，按空集合处理。
273	  // 采购单编号独立于库存单据编号空间，允许与入库/到货/冲销单同名。
274	  if (data.purchases !== undefined) {
275	    if (!isPlainObject(data.purchases)) throw bad('purchases 不是对象');
276	    for (const [poId, rec] of Object.entries(data.purchases)) {
277	      if (typeof poId !== 'string' || poId.trim() === '') throw bad('存在非法采购单编号');
278	      if (
279	        !isPlainObject(rec) ||
280	        typeof rec.supplier !== 'string' || rec.supplier.trim() === '' ||
281	        typeof rec.wh !== 'string' || rec.wh.trim() === '' ||
282	        !isPlainObject(rec.ordered) ||
283	        !Array.isArray(rec.resultLines) || !rec.resultLines.every((l) => typeof l === 'string')
284	      )
285	        throw bad(`采购单 ${poId} 的记录非法`);
286	      if (rec.poId !== undefined && rec.poId !== poId) throw bad(`采购单 ${poId} 的内嵌编号不一致`);
287	      const ordered = nullProto<Record<string, number>>();
288	      for (const [pid, qty] of Object.entries(rec.ordered)) {
289	        if (pid.trim() === '' || !isPosSafeInt(qty)) throw bad(`采购单 ${poId} 存在非法订购明细`);
290	        ordered[pid] = qty;
291	      }
292	      if (Object.keys(ordered).length === 0) throw bad(`采购单 ${poId} 至少需要一种商品`);
293	      store.purchases[poId] = {
294	        poId, supplier: rec.supplier, wh: rec.wh, ordered, resultLines: rec.resultLines,
295	      };
296	    }
297	  }
298	
299	  // arrivals 为新增字段：合法旧数据没有该字段，按空集合处理。
300	  // 到货单与入库/出库/调拨/盘点/冲销单共用全局唯一编号空间。
301	  if (data.arrivals !== undefined) {
302	    if (!isPlainObject(data.arrivals)) throw bad('arrivals 不是对象');
303	    for (const [arrId, rec] of Object.entries(data.arrivals)) {
304	      if (typeof arrId !== 'string' || arrId.trim() === '') throw bad('存在非法到货单编号');
305	      if (store.docs[arrId] !== undefined) throw bad(`到货单编号 ${arrId} 与原始库存单据编号冲突`);
306	      if (
307	        !isPlainObject(rec) ||
308	        typeof rec.poId !== 'string' || rec.poId.trim() === '' ||
309	        typeof rec.wh !== 'string' || rec.wh.trim() === '' ||
310	        !isPlainObject(rec.qty) ||
311	        !Array.isArray(rec.resultLines) || !rec.resultLines.every((l) => typeof l === 'string')
312	      )
313	        throw bad(`到货单 ${arrId} 的记录非法`);
314	      const qty = nullProto<Record<string, number>>();
315	      for (const [pid, q] of Object.entries(rec.qty)) {
316	        if (pid.trim() === '' || !isPosSafeInt(q)) throw bad(`到货单 ${arrId} 存在非法到货明细`);
317	        qty[pid] = q;
318	      }
319	      if (Object.keys(qty).length === 0) throw bad(`到货单 ${arrId} 至少需要一种商品`);
320	      const po = store.purchases[rec.poId];
321	      if (po === undefined) throw bad(`到货单 ${arrId} 指向的采购单 ${rec.poId} 不存在`);
322	      if (rec.wh !== po.wh) throw bad(`到货单 ${arrId} 的收货仓与采购单 ${rec.poId} 不一致`);
323	      for (const [pid, q] of Object.entries(qty)) {
324	        if (po.ordered[pid] === undefined)
325	          throw bad(`到货单 ${arrId} 含采购单 ${rec.poId} 未订购的商品 ${pid}`);
326	        if (q > po.ordered[pid])
327	          throw bad(`到货单 ${arrId} 商品 ${pid} 到货量超过订购量`);
328	      }
329	      store.arrivals[arrId] = { poId: rec.poId, wh: rec.wh, qty, resultLines: rec.resultLines };
330	    }
331	  }
332	
333	  // reversals 为新增字段：合法旧数据没有该字段，按空集合处理。
334	  // 原单既可以是入库/出库/调拨/盘点单，也可以是到货单；冲销单不可冲销。
335	  if (data.reversals !== undefined) {
336	    if (!isPlainObject(data.reversals)) throw bad('reversals 不是对象');
337	    for (const [revId, rec] of Object.entries(data.reversals)) {
338	      if (typeof revId !== 'string' || revId.trim() === '') throw bad('存在非法冲销单编号');
339	      if (!isPlainObject(rec) || typeof rec.orig !== 'string' || rec.orig.trim() === '' ||
340	          !Array.isArray(rec.resultLines) || !rec.resultLines.every((l) => typeof l === 'string'))
341	        throw bad(`冲销单 ${revId} 的记录非法`);
342	      if (store.docs[revId] !== undefined) throw bad(`冲销单编号 ${revId} 与原始库存单据编号冲突`);
343	      if (store.arrivals[revId] !== undefined) throw bad(`冲销单编号 ${revId} 与到货单编号冲突`);
344	      const origRec = store.docs[rec.orig];
345	      const origArr = store.arrivals[rec.orig];
346	      if (origRec === undefined && origArr === undefined) {
347	        // 用 data.reversals 判定，避免依赖键的先后顺序（此时 store.reversals 可能尚未装全）
348	        if (isPlainObject((data.reversals as Record<string, unknown>)[rec.orig]))
349	          throw bad(`冲销单 ${rec.orig} 不可被再次冲销（冲销单不能冲销冲销单）`);
350	        if (store.purchases[rec.orig] !== undefined)
351	          throw bad(`冲销单 ${revId} 指向的 ${rec.orig} 是采购单，采购单不可冲销`);
352	        throw bad(`冲销单 ${revId} 指向的原单 ${rec.orig} 不存在`);
353	      }
354	      store.reversals[revId] = { orig: rec.orig, resultLines: rec.resultLines };
355	    }
356	    // 每张原单最多被成功冲销一次（库存单与到货单统一校验）
357	    const origSeen = nullProto<Record<string, string>>();
358	    for (const [revId, rec] of Object.entries(store.reversals)) {
359	      if (origSeen[rec.orig] !== undefined)
360	        throw bad(`原单 ${rec.orig} 被多张冲销单关联（${origSeen[rec.orig]}、${revId}）`);
361	      origSeen[rec.orig] = revId;
362	    }
363	    // 冲销单不可冲销：冲销关系不能指向另一张冲销单
364	    for (const rec of Object.values(store.reversals)) {
365	      if (store.reversals[rec.orig] !== undefined)
366	        throw bad(`冲销单 ${rec.orig} 不可被再次冲销`);
367	    }
368	    // 冲销流水必须能找到所属冲销单
369	    for (const e of store.entries) {
370	      if (REV_ENTRY_TYPES.has(e.type) && store.reversals[e.doc] === undefined)
371	        throw bad(`流水引用了不存在的冲销单 ${e.doc}`);
372	    }
373	  }
374	
375	  // 到货流水必须能找到所属到货单，且逐项数量/采购单/收货仓与记录一致
376	  const arrivalEntrySeen = nullProto<Record<string, Record<string, number>>>();
377	  for (const e of store.entries) {
378	    if (e.type !== 'arrival') continue;
379	    const arr = store.arrivals[e.doc];
380	    if (arr === undefined) throw bad(`流水引用了不存在的到货单 ${e.doc}`);
381	    if (e.po !== arr.poId) throw bad(`到货单 ${e.doc} 流水的采购单编号与记录不一致`);
382	    if (e.wh !== arr.wh) throw bad(`到货单 ${e.doc} 流水的收货仓与记录不一致`);
383	    const perProduct = (arrivalEntrySeen[e.doc] ??= nullProto<Record<string, number>>());
384	    perProduct[e.product] = (perProduct[e.product] ?? 0) + e.qty!;
385	  }
386	  for (const [arrId, arr] of Object.entries(store.arrivals)) {
387	    const seen = arrivalEntrySeen[arrId];
388	    if (seen === undefined) throw bad(`到货单 ${arrId} 缺少到货流水`);
389	    for (const [pid, q] of Object.entries(arr.qty)) {
390	      if (seen[pid] !== q) throw bad(`到货单 ${arrId} 商品 ${pid} 的流水数量与记录不一致`);
391	    }
392	    for (const pid of Object.keys(seen)) {
393	      if (arr.qty[pid] === undefined) throw bad(`到货单 ${arrId} 的流水含记录中没有的商品 ${pid}`);
394	    }
395	  }
396	
397	  // 冲销到货流水逐项数量必须与原到货单一致
398	  for (const e of store.entries) {
399	    if (e.type !== 'arrival-rev') continue;
400	    const rev = store.reversals[e.doc];
401	    if (rev === undefined) throw bad(`冲销到货流水引用了不存在的冲销单 ${e.doc}`);
402	    const arr = store.arrivals[rev.orig];
403	    if (arr === undefined) throw bad(`冲销单 ${e.doc} 指向的到货原单 ${rev.orig} 不存在`);
404	    if (e.po !== arr.poId) throw bad(`冲销单 ${e.doc} 流水的采购单编号与原到货单不一致`);
405	    if (arr.qty[e.product] !== e.qty)
406	      throw bad(`冲销单 ${e.doc} 商品 ${e.product} 的冲销量与原到货单不一致`);
407	  }
408	
409	  // 冲销流水类型必须与原单业务类型一致（入库→in-rev、到货→arrival-rev 等）
410	  const revIdsWithEntries = nullProto<Record<string, boolean>>();
411	  for (const [revId, rev] of Object.entries(store.reversals)) {
412	    let expected: EntryType;
413	    const origDoc = store.docs[rev.orig];
414	    if (origDoc !== undefined) expected = `${origDoc.content.type}-rev` as EntryType;
415	    else expected = 'arrival-rev'; // 原单为到货单（前面已确认二者必居其一）
416	    for (const e of store.entries) {
417	      if (e.doc !== revId) continue;
418	      revIdsWithEntries[revId] = true;
419	      if (e.type !== expected)
420	        throw bad(`冲销单 ${revId} 的流水类型与原单 ${rev.orig} 的业务类型不一致`);
421	    }
422	  }
423	  for (const revId of Object.keys(store.reversals)) {
424	    if (revIdsWithEntries[revId] !== true) throw bad(`冲销单 ${revId} 缺少冲销流水`);
425	  }
426	
427	  // 采购进度不变量：任一商品“未冲销累计到货”不得超过订购量
428	  for (const [poId, po] of Object.entries(store.purchases)) {
429	    const arrived = nullProto<Record<string, number>>();
430	    for (const [arrId, arr] of Object.entries(store.arrivals)) {
431	      if (arr.poId !== poId) continue;
432	      const isReversed = Object.values(store.reversals).some((r) => r.orig === arrId);
433	      if (isReversed) continue; // 已整单冲销的到货不再计入有效到货
434	      for (const [pid, q] of Object.entries(arr.qty)) {
435	        arrived[pid] = (arrived[pid] ?? 0) + q;
436	        if (arrived[pid] > po.ordered[pid])
437	          throw bad(`采购单 ${poId} 商品 ${pid} 未冲销累计到货超过订购量`);
438	      }
439	    }
440	  }
441	
442	  return store;
443	}
