445	function saveStore(dataDir: string, store: Store): void {
446	  const path = dataPath(dataDir);
447	  const tmp = join(dataDir, `.${DATA_FILENAME}.${process.pid}.tmp`);
448	  try {
449	    mkdirSync(dataDir, { recursive: true });
450	    writeFileSync(tmp, JSON.stringify(store, null, 2) + '\n', 'utf8');
451	    renameSync(tmp, path);
452	  } catch (e) {
453	    throw new DataError(`保存数据失败，已有数据保持不变：${(e as Error).message}`);
454	  }
455	}
