457	// ---------- 参数解析 ----------
458	
459	interface ParsedArgs {
460	  positionals: string[];
461	  flags: Record<string, string>;
462	  multi: Record<string, string[]>;
463	}
464	
465	function parseArgs(
466	  tokens: string[],
467	  singles: string[],
468	  multis: string[] = [],
469	): ParsedArgs {
470	  const out: ParsedArgs = { positionals: [], flags: {}, multi: {} };
471	  const singleSet = new Set(singles);
472	  const multiSet = new Set(multis);
473	
474	  for (let i = 0; i < tokens.length; i++) {
475	    const tok = tokens[i];
476	    if (tok.startsWith('--')) {
477	      let key = tok;
478	      let value: string | undefined;
479	      const eq = tok.indexOf('=');
480	      if (eq >= 0) {
481	        key = tok.slice(0, eq);
482	        value = tok.slice(eq + 1);
483	      }
484	      if (!singleSet.has(key) && !multiSet.has(key)) throw new UsageError(`未知参数：${tok}`);
485	      if (value === undefined) {
486	        if (i + 1 >= tokens.length) throw new UsageError(`参数 ${key} 缺少取值`);
487	        value = tokens[++i];
488	      }
489	      if (multiSet.has(key)) (out.multi[key] ??= []).push(value);
490	      else if (out.flags[key] !== undefined) throw new UsageError(`参数 ${key} 重复指定`);
491	      else out.flags[key] = value;
492	    } else {
493	      out.positionals.push(tok);
494	    }
495	  }
496	  return out;
497	}
498	
499	function parseItem(raw: string, merged: Map<string, number>): void {
500	  const idx = raw.indexOf(':');
501	  if (idx <= 0) throw new BizError(`明细格式应为 “商品编号:数量”：${raw}`);
502	  const pid = trimOrThrow('商品编号', raw.slice(0, idx));
503	  const qtyRaw = raw.slice(idx + 1).trim();
504	  if (!/^\d+$/.test(qtyRaw)) throw new BizError(`商品 ${pid} 的数量必须为正安全整数：${qtyRaw}`);
505	  const qty = Number(qtyRaw);
506	  if (!Number.isSafeInteger(qty) || qty <= 0) throw new BizError(`商品 ${pid} 的数量必须为正安全整数：${qtyRaw}`);
507	  const sum = (merged.get(pid) ?? 0) + qty; // 同单同商品先合并
508	  if (!Number.isSafeInteger(sum)) throw new BizError(`商品 ${pid} 累计数量超出安全整数范围`);
509	  merged.set(pid, sum);
510	}
511	
512	interface DocRequest {
513	  type: DocType;
514	  docId: string;
515	  wh?: string;
516	  from?: string;
517	  to?: string;
518	  items: Map<string, number>;
519	}
520	
521	function parseDocArgs(type: DocType, tokens: string[]): DocRequest {
522	  const args = parseArgs(tokens, type === 'transfer' ? ['--from', '--to'] : ['--wh'], ['--item']);
523	  const docId = args.positionals[0];
524	  if (docId === undefined || args.positionals.length !== 1)
525	    throw new UsageError(`用法：单据命令需要且仅需要一个单据编号`);
526	
527	  const items = new Map<string, number>();
528	  for (const raw of args.multi['--item'] ?? []) parseItem(raw, items);
529	  if (items.size === 0) throw new UsageError('单据至少需要一条 --item 商品编号:数量 明细');
530	
531	  const req: DocRequest = { type, docId: trimOrThrow('单据编号', docId), items };
532	  if (type === 'transfer') {
533	    if (args.flags['--from'] === undefined || args.flags['--to'] === undefined)
534	      throw new UsageError('调拨单必须提供 --from <调出仓> 与 --to <调入仓>');
535	    req.from = trimOrThrow('调出仓标识', args.flags['--from']);
536	    req.to = trimOrThrow('调入仓标识', args.flags['--to']);
537	    if (req.from === req.to) throw new BizError('调拨单的调出仓与调入仓不能相同');
538	  } else {
539	    if (args.flags['--wh'] === undefined) throw new UsageError('入库/出库单必须提供 --wh <仓库>');
540	    req.wh = trimOrThrow('仓库标识', args.flags['--wh']);
541	  }
542	  return req;
543	}
544	
545	interface CountItem {
546	  expected: number; // 预期账面量
547	  actual: number; // 实盘量
548	}
549	
550	interface CountRequest {
551	  docId: string;
552	  wh: string;
553	  items: Map<string, CountItem>;
554	}
555	
556	function parseNonNegInt(label: string, raw: string): number {
557	  const s = raw.trim();
558	  if (!/^\d+$/.test(s)) throw new BizError(`${label}必须为非负安全整数：${raw}`);
559	  const n = Number(s);
560	  if (!Number.isSafeInteger(n)) throw new BizError(`${label}必须为非负安全整数：${raw}`);
561	  return n;
562	}
563	
564	function parseCountArgs(tokens: string[]): CountRequest {
565	  const args = parseArgs(tokens, ['--wh'], ['--item']);
566	  const docId = args.positionals[0];
567	  if (docId === undefined || args.positionals.length !== 1)
568	    throw new UsageError('用法：count <单据编号> --wh <仓库> --item <商品编号:预期账面量:实盘量> [...]');
569	  if (args.flags['--wh'] === undefined) throw new UsageError('盘点单必须提供 --wh <仓库>');
570	
571	  const items = new Map<string, CountItem>();
572	  for (const raw of args.multi['--item'] ?? []) {
573	    const parts = raw.split(':');
574	    if (parts.length !== 3)
575	      throw new BizError(`盘点明细格式应为 “商品编号:预期账面量:实盘量”：${raw}`);
576	    const pid = trimOrThrow('商品编号', parts[0]);
577	    const expected = parseNonNegInt(`商品 ${pid} 的预期账面量`, parts[1]);
578	    const actual = parseNonNegInt(`商品 ${pid} 的实盘量`, parts[2]);
579	    if (items.has(pid)) throw new BizError(`盘点单中商品 ${pid} 重复出现，拒绝提交`);
580	    items.set(pid, { expected, actual });
581	  }
582	  if (items.size === 0)
583	    throw new UsageError('盘点单至少需要一条 --item 商品编号:预期账面量:实盘量 明细');
584	
585	  return { docId: trimOrThrow('单据编号', docId), wh: trimOrThrow('仓库标识', args.flags['--wh']), items };
586	}
587	
588	// ---------- 采购单与到货参数 ----------
589	
590	interface PurchaseRequest {
591	  poId: string;
592	  supplier: string;
593	  wh: string;
594	  items: Map<string, number>; // 合并后的订购量
595	}
596	
597	interface ArrivalRequest {
598	  arrId: string;
599	  poId: string;
600	  items: Map<string, number>; // 合并后的本次到货量
601	}
602	
603	function parsePurchaseArgs(tokens: string[]): PurchaseRequest {
604	  const args = parseArgs(tokens, ['--supplier', '--wh'], ['--item']);
605	  const poRaw = args.positionals[0];
606	  if (poRaw === undefined || args.positionals.length !== 1)
607	    throw new UsageError('用法：po register <采购编号> --supplier <供应商名称> --wh <收货仓> --item <商品编号:订购量> [...]');
608	  if (args.flags['--supplier'] === undefined) throw new UsageError('采购单必须提供 --supplier <供应商名称>');
609	  if (args.flags['--wh'] === undefined) throw new UsageError('采购单必须提供 --wh <收货仓>');
610	
611	  const items = new Map<string, number>();
612	  for (const raw of args.multi['--item'] ?? []) parseItem(raw, items);
613	  if (items.size === 0) throw new UsageError('采购单至少需要一条 --item 商品编号:订购量 明细');
614	
615	  return {
616	    poId: trimOrThrow('采购编号', poRaw),
617	    supplier: trimOrThrow('供应商名称', args.flags['--supplier']),
618	    wh: trimOrThrow('收货仓标识', args.flags['--wh']),
619	    items,
620	  };
621	}
622	
623	function parseArrivalArgs(tokens: string[]): ArrivalRequest {
624	  const args = parseArgs(tokens, ['--po'], ['--item']);
625	  const arrRaw = args.positionals[0];
626	  if (arrRaw === undefined || args.positionals.length !== 1)
627	    throw new UsageError('用法：arrival <到货单编号> --po <采购编号> --item <商品编号:到货量> [...]');
628	  if (args.flags['--po'] === undefined) throw new UsageError('到货必须通过 --po <采购编号> 指定所属采购单（收货仓取采购单）');
629	
630	  const items = new Map<string, number>();
631	  for (const raw of args.multi['--item'] ?? []) parseItem(raw, items);
632	  if (items.size === 0) throw new UsageError('到货单至少需要一条 --item 商品编号:到货量 明细');
633	
634	  return { arrId: trimOrThrow('到货单编号', arrRaw), poId: trimOrThrow('采购编号', args.flags['--po']), items };
635	}
