637	// ---------- 整批导入文件解析 ----------
638	
639	type ImportRequest =
640	  | { kind: 'doc'; req: DocRequest }
641	  | { kind: 'count'; req: CountRequest }
642	  | { kind: 'reverse'; docId: string; orig: string }
643	  | { kind: 'po'; req: PurchaseRequest }
644	  | { kind: 'arrival'; req: ArrivalRequest };
645	
646	/** 读取导入文件：无法读取属于读写失败（退出 1），不改变任何已提交状态。 */
647	function readImportFile(file: string): string {
648	  try {
649	    return readFileSync(file, 'utf8');
650	  } catch (e) {
651	    throw new DataError(`无法读取导入文件 ${file}：${(e as Error).message}（不会改变任何已提交数据）`);
652	  }
653	}
654	
655	/**
656	 * 解析整批导入文件。文件级结构错误（非合法 JSON、根不是数组、空列表）属于文件
657	 * 格式错误（退出 2）；逐项格式不合法属于业务拒绝（退出 1），指出位置与原因。
658	 */
659	function parseImportFile(raw: string): ImportRequest[] {
660	  let data: unknown;
661	  try {
662	    data = JSON.parse(raw);
663	  } catch (e) {
664	    throw new UsageError(`导入文件不是合法 JSON：${(e as Error).message}`);
665	  }
666	  if (!Array.isArray(data)) throw new UsageError('导入文件格式错误：根节点必须是单据对象组成的有序数组');
667	  if (data.length === 0) throw new UsageError('导入文件格式错误：单据列表至少包含一项');
668	
669	  const out: ImportRequest[] = [];
670	  // 顶层位置一律标注 1 起序号，便于纠正
671	  const at = (i: number, msg: string): BizError => new BizError(`第 ${i + 1} 项：${msg}`);
672	
673	  const requireString = (obj: Record<string, unknown>, key: string, label: string, i: number): string => {
674	    const v = obj[key];
675	    if (v === undefined) throw at(i, `缺少${label}字段 "${key}"`);
676	    if (typeof v !== 'string') throw at(i, `${label}字段 "${key}" 必须是字符串`);
677	    const s = v.trim();
678	    if (s === '') throw at(i, `${label}去除首尾空白后不能为空`);
679	    return s;
680	  };
681	
682	  const checkUnknown = (obj: Record<string, unknown>, allowed: readonly string[], i: number): void => {
683	    for (const k of Object.keys(obj)) {
684	      if (!allowed.includes(k)) throw at(i, `含不支持的字段 "${k}"（允许字段：${allowed.join('、')}）`);
685	    }
686	  };
687	
688	  const parseQtyItems = (obj: Record<string, unknown>, i: number): Map<string, number> => {
689	    const v = obj.items;
690	    if (v === undefined) throw at(i, '缺少商品明细字段 "items"');
691	    if (!Array.isArray(v)) throw at(i, '"items" 必须是明细对象数组');
692	    if (v.length === 0) throw at(i, '商品明细至少一项');
693	    const merged = new Map<string, number>();
694	    v.forEach((entry, j) => {
695	      if (!isPlainObject(entry)) throw at(i, `第 ${j + 1} 条明细不是对象`);
696	      const e = entry as Record<string, unknown>;
697	      checkUnknown(e, ['product', 'qty'], i);
698	      const pid = e.product;
699	      if (typeof pid !== 'string') throw at(i, `第 ${j + 1} 条明细缺少商品编号字段 "product" 或不是字符串`);
700	      const p = pid.trim();
701	      if (p === '') throw at(i, `第 ${j + 1} 条明细的商品编号去空白后不能为空`);
702	      if (!isPosSafeInt(e.qty)) throw at(i, `商品 ${p} 的数量必须为正安全整数`);
703	      const sum = (merged.get(p) ?? 0) + (e.qty as number); // 同单同商品先合并
704	      if (!Number.isSafeInteger(sum)) throw at(i, `商品 ${p} 累计数量超出安全整数范围`);
705	      merged.set(p, sum);
706	    });
707	    return merged;
708	  };
709	
710	  const parseCountItems = (obj: Record<string, unknown>, i: number): Map<string, CountItem> => {
711	    const v = obj.items;
712	    if (v === undefined) throw at(i, '缺少商品明细字段 "items"');
713	    if (!Array.isArray(v)) throw at(i, '"items" 必须是明细对象数组');
714	    if (v.length === 0) throw at(i, '商品明细至少一项');
715	    const items = new Map<string, CountItem>();
716	    v.forEach((entry, j) => {
717	      if (!isPlainObject(entry)) throw at(i, `第 ${j + 1} 条明细不是对象`);
718	      const e = entry as Record<string, unknown>;
719	      checkUnknown(e, ['product', 'expected', 'actual'], i);
720	      const pid = e.product;
721	      if (typeof pid !== 'string') throw at(i, `第 ${j + 1} 条明细缺少商品编号字段 "product" 或不是字符串`);
722	      const p = pid.trim();
723	      if (p === '') throw at(i, `第 ${j + 1} 条明细的商品编号去空白后不能为空`);
724	      if (!isNonNegSafeInt(e.expected)) throw at(i, `商品 ${p} 的预期账面量必须为非负安全整数`);
725	      if (!isNonNegSafeInt(e.actual)) throw at(i, `商品 ${p} 的实盘量必须为非负安全整数`);
726	      if (items.has(p)) throw at(i, `盘点明细中商品 ${p} 重复出现，拒绝提交`); // 盘点不合并
727	      items.set(p, { expected: e.expected, actual: e.actual });
728	    });
729	    return items;
730	  };
731	
732	  data.forEach((rawItem, i) => {
733	    if (!isPlainObject(rawItem)) throw at(i, '不是单据对象');
734	    const item = rawItem as Record<string, unknown>;
735	    if (item.type === undefined) throw at(i, '缺少业务类型字段 "type"');
736	    if (typeof item.type !== 'string') throw at(i, '业务类型字段 "type" 必须是字符串');
737	
738	    switch (item.type) {
739	      case 'in':
740	      case 'out': {
741	        checkUnknown(item, ['type', 'id', 'wh', 'items'], i);
742	        const docId = requireString(item, 'id', '单据编号', i);
743	        const wh = requireString(item, 'wh', '仓库标识', i);
744	        out.push({ kind: 'doc', req: { type: item.type, docId, wh, items: parseQtyItems(item, i) } });
745	        break;
746	      }
747	      case 'transfer': {
748	        checkUnknown(item, ['type', 'id', 'from', 'to', 'items'], i);
749	        const docId = requireString(item, 'id', '单据编号', i);
750	        const from = requireString(item, 'from', '调出仓标识', i);
751	        const to = requireString(item, 'to', '调入仓标识', i);
752	        if (from === to) throw at(i, '调拨单的调出仓与调入仓不能相同');
753	        out.push({ kind: 'doc', req: { type: 'transfer', docId, from, to, items: parseQtyItems(item, i) } });
754	        break;
755	      }
756	      case 'count': {
757	        checkUnknown(item, ['type', 'id', 'wh', 'items'], i);
758	        const docId = requireString(item, 'id', '单据编号', i);
759	        const wh = requireString(item, 'wh', '仓库标识', i);
760	        out.push({ kind: 'count', req: { docId, wh, items: parseCountItems(item, i) } });
761	        break;
762	      }
763	      case 'reverse': {
764	        checkUnknown(item, ['type', 'id', 'orig'], i);
765	        const docId = requireString(item, 'id', '冲销单编号', i);
766	        const orig = requireString(item, 'orig', '原单编号', i);
767	        out.push({ kind: 'reverse', docId, orig });
768	        break;
769	      }
770	      case 'po': {
771	        checkUnknown(item, ['type', 'id', 'supplier', 'wh', 'items'], i);
772	        const poId = requireString(item, 'id', '采购编号', i);
773	        const supplier = requireString(item, 'supplier', '供应商名称', i);
774	        const wh = requireString(item, 'wh', '收货仓标识', i);
775	        out.push({ kind: 'po', req: { poId, supplier, wh, items: parseQtyItems(item, i) } });
776	        break;
777	      }
778	      case 'arrival': {
779	        checkUnknown(item, ['type', 'id', 'po', 'items'], i);
780	        const arrId = requireString(item, 'id', '到货单编号', i);
781	        const poId = requireString(item, 'po', '采购编号', i);
782	        out.push({ kind: 'arrival', req: { arrId, poId, items: parseQtyItems(item, i) } });
783	        break;
784	      }
785	      default:
786	        throw at(i, `不支持的业务类型 "${String(item.type)}"，只允许 in、out、transfer、count、reverse、po、arrival`);
787	    }
788	  });
789	
790	  return out;
791	}
792	
793	// ---------- 业务核心 ----------
794	
795	const MAX_SAFE = Number.MAX_SAFE_INTEGER;
796	
797	/** 带符号数量文本：正数加 +，负数保留 -，零为 0。 */
798	function fmtSigned(n: number): string {
799	  return n > 0 ? `+${n}` : String(n);
800	}
801	
802	function canonicalContent(req: DocRequest): Record<string, unknown> {
803	  const items: Record<string, number> = nullProto();
804	  for (const pid of [...req.items.keys()].sort()) items[pid] = req.items.get(pid)!;
805	  if (req.type === 'transfer') return { type: req.type, from: req.from!, to: req.to!, items };
806	  return { type: req.type, wh: req.wh!, items };
807	}
808	
809	function getStock(stock: Store['stock'], pid: string, wh: string): number {
810	  return stock[pid]?.[wh] ?? 0;
811	}
812	
813	function setStock(stock: Store['stock'], pid: string, wh: string, qty: number): void {
814	  (stock[pid] ??= nullProto<Record<string, number>>())[wh] = qty;
815	}
816	
817	/**
818	 * 深拷贝余量草稿。必须自建 null 原型容器：structuredClone 不保留 null 原型，
819	 * 普通对象在 "__proto__"/"constructor" 等商品或仓库键下会发生原型串改。
820	 */
821	function cloneStock(stock: Store['stock']): Store['stock'] {
822	  const out = nullProto<Store['stock']>();
823	  for (const pid of Object.keys(stock)) {
824	    const whMap = nullProto<Record<string, number>>();
825	    for (const wh of Object.keys(stock[pid])) whMap[wh] = stock[pid][wh];
826	    out[pid] = whMap;
827	  }
828	  return out;
829	}
830	
831	function canonicalCountContent(req: CountRequest): Record<string, unknown> {
832	  const items: Record<string, unknown> = nullProto();
833	  for (const pid of [...req.items.keys()].sort()) {
834	    const it = req.items.get(pid)!;
835	    items[pid] = { expected: it.expected, actual: it.actual };
836	  }
837	  return { type: 'count', wh: req.wh, items };
838	}
839	
840	/** 采购单规范化内容：明细按商品编号排序，比较时与明细顺序无关。 */
841	function canonicalPurchaseContent(req: PurchaseRequest): {
842	  supplier: string;
843	  wh: string;
844	  ordered: Record<string, number>;
845	} {
846	  const ordered: Record<string, number> = nullProto();
847	  for (const pid of [...req.items.keys()].sort()) ordered[pid] = req.items.get(pid)!;
848	  return { supplier: req.supplier, wh: req.wh, ordered };
849	}
850	
851	/** 到货明细规范化：合并后数量按商品编号排序。 */
852	function canonicalArrivalItems(items: Map<string, number>): Record<string, number> {
853	  const out: Record<string, number> = nullProto();
854	  for (const pid of [...items.keys()].sort()) out[pid] = items.get(pid)!;
855	  return out;
856	}
857	
858	interface ApplyOutcome {
859	  duplicate: boolean;
860	  header: string; // 结果首行汇总
861	  lines: string[]; // 逐项明细结果
862	  repeatedFrom?: 'store' | 'batch'; // 重复项来自导入前已存数据，还是本批此前各项
863	}
864	
865	/**
866	 * 账务模拟器：单条命令与整批导入共用。所有变动先落在草稿余量与新增流水上，
867	 * 编号去重视图（docs/revs）在模拟期间即时更新但不写回 base，全部项通过后由
868	 * commit 一次性落库；模拟途中抛错则 base 与磁盘均不受影响。
869	 */
870	class Ledger {
871	  private readonly base: Store;
872	  private readonly draft: Store['stock'];
873	  private readonly additions: LedgerEntry[] = [];
874	  private seq: number;
875	  private readonly docs: Record<string, DocRecord> = nullProto();
876	  private readonly revs: Record<string, ReversalRecord> = nullProto();
877	  private readonly pos: Record<string, PurchaseRecord> = nullProto();
878	  private readonly arrivals: Record<string, ArrivalRecord> = nullProto();
879	  private readonly reversedOrigs = new Set<string>();
880	  private readonly newDocIds: string[] = [];
881	  private readonly newRevIds: string[] = [];
882	  private readonly newPoIds: string[] = [];
883	  private readonly newArrivalIds: string[] = [];
884	
885	  constructor(store: Store) {
886	    this.base = store;
887	    this.draft = cloneStock(store.stock);
888	    this.seq = store.entries.length;
889	    for (const [id, rec] of Object.entries(store.docs)) this.docs[id] = rec;
890	    for (const [id, rec] of Object.entries(store.reversals)) {
891	      this.revs[id] = rec;
892	      this.reversedOrigs.add(rec.orig);
893	    }
894	    for (const [id, rec] of Object.entries(store.purchases)) this.pos[id] = rec;
895	    for (const [id, rec] of Object.entries(store.arrivals)) this.arrivals[id] = rec;
896	  }
897	
898	  /** 是否有新生效单据：无新单据（全部重复）时 commit 不改写数据。 */
899	  get changed(): boolean {
900	    return (
901	      this.newDocIds.length +
902	      this.newRevIds.length +
903	      this.newPoIds.length +
904	      this.newArrivalIds.length > 0
905	    );
906	  }
907	
908	  /** 重建原始单据结果首行，供幂等重放。 */
909	  private docHeader(docId: string, rec: DocRecord): string {
910	    const c = rec.content;
911	    const n = Object.keys(c.items as Record<string, unknown>).length;
912	    return c.type === 'count'
913	      ? `盘点单 ${docId} 提交成功，仓库 ${c.wh as string}，共 ${n} 种商品：`
914	      : `${c.type === 'in' ? '入库' : c.type === 'out' ? '出库' : '调拨'}单 ${docId} 提交成功，共 ${n} 种商品：`;
915	  }
916	
917	  /** 重建冲销单结果首行，供幂等重放。 */
918	  private revHeader(revId: string, rec: ReversalRecord): string {
919	    const origDoc = this.docs[rec.orig];
920	    if (origDoc !== undefined) {
921	      const type = origDoc.content.type as string;
922	      const label = type === 'in' ? '入库' : type === 'out' ? '出库' : type === 'transfer' ? '调拨' : '盘点';
923	      const n = Object.keys(origDoc.content.items as Record<string, unknown>).length;
924	      return `冲销单 ${revId} 提交成功，冲销${label}原单 ${rec.orig}，共 ${n} 种商品：`;
925	    }
926	    // 原单为到货单（能进入去重视图的冲销单必然指向存在的原单）
927	    const arr = this.arrivals[rec.orig];
928	    const n = Object.keys(arr.qty).length;
929	    return `冲销单 ${revId} 提交成功，冲销到货原单 ${rec.orig}（采购单 ${arr.poId}），共 ${n} 种商品：`;
930	  }
931	
932	  private repeatedPoSource(poId: string): 'store' | 'batch' {
933	    return this.base.purchases[poId] !== undefined ? 'store' : 'batch';
934	  }
935	
936	  private repeatedArrivalSource(arrId: string): 'store' | 'batch' {
937	    return this.base.arrivals[arrId] !== undefined ? 'store' : 'batch';
938	  }
939	
940	  /** 计算某采购单各商品当前“未冲销累计到货”（仅计入尚未被整单冲销的到货单）。 */
941	  private effectiveArrived(poId: string): Record<string, number> {
942	    const arrived = nullProto<Record<string, number>>();
943	    for (const [arrId, arr] of Object.entries(this.arrivals)) {
944	      if (arr.poId !== poId || this.reversedOrigs.has(arrId)) continue;
945	      for (const [pid, q] of Object.entries(arr.qty)) arrived[pid] = (arrived[pid] ?? 0) + q;
946	    }
947	    return arrived;
948	  }
949	
950	  /**
951	   * 采购单登记：只登记订购信息，不改动任何库存，登记成功后内容不可修改。
952	   * 采购单编号独立于库存单据编号空间，允许与入库/到货/冲销单同名；
953	   * 同号同内容重放返回原登记结果且不重置到货进度，同号不同内容拒绝。
954	   */
955	  applyPurchase(req: PurchaseRequest): ApplyOutcome {
956	    const content = canonicalPurchaseContent(req);
957	    const existed = this.pos[req.poId];
958	    if (existed !== undefined) {
959	      if (
960	        existed.supplier !== req.supplier ||
961	        existed.wh !== req.wh ||
962	        stableStringify(existed.ordered) !== stableStringify(content.ordered as Record<string, number>)
963	      )
964	        throw new BizError(`采购编号 ${req.poId} 已用于内容不同的采购单，拒绝提交且不重置到货进度`);
965	      return {
966	        duplicate: true,
967	        header: this.poHeader(req.poId, existed),
968	        lines: existed.resultLines,
969	        repeatedFrom: this.repeatedPoSource(req.poId),
970	      };
971	    }
972	
973	    for (const pid of req.items.keys()) {
974	      if (this.base.products[pid] === undefined) throw new BizError(`商品未登记，拒绝整单：${pid}`);
975	    }
976	
977	    const ordered: Record<string, number> = nullProto();
978	    const reportLines: string[] = [];
979	    for (const pid of [...req.items.keys()].sort()) {
980	      const qty = req.items.get(pid)!;
981	      ordered[pid] = qty;
982	      reportLines.push(`订购 ${pid} x${qty}，待到货 ${qty}`);
983	    }
984	
985	    this.pos[req.poId] = {
986	      poId: req.poId, supplier: req.supplier, wh: req.wh, ordered, resultLines: reportLines,
987	    };
988	    this.newPoIds.push(req.poId);
989	
990	    return { duplicate: false, header: this.poHeader(req.poId, this.pos[req.poId]), lines: reportLines };
991	  }
992	
993	  private poHeader(poId: string, rec: PurchaseRecord): string {
994	    return `采购单 ${poId} 登记成功，供应商 ${rec.supplier}，收货仓 ${rec.wh}，共 ${Object.keys(rec.ordered).length} 种商品（登记不改动库存）：`;
995	  }
996	
997	  /**
998	   * 采购到货：独立到货单编号，引用已登记采购单，可分次收部分商品；
999	   * 仅能收采购单内商品，并入采购单收货仓。各商品“未冲销累计到货 + 本次”
1000	   * 不得超过订购量；任一明细非法、超收或库存溢出整单拒绝。
1001	   * 到货单与入库/出库/调拨/盘点/冲销单共用唯一编号空间；普通入库不能绑定采购。
1002	   */
1003	  applyArrival(req: ArrivalRequest): ApplyOutcome {
1004	    const existed = this.arrivals[req.arrId];
1005	    if (existed !== undefined) {
1006	      if (
1007	        existed.poId !== req.poId ||
1008	        stableStringify(existed.qty) !== stableStringify(canonicalArrivalItems(req.items))
1009	      )
1010	        throw new BizError(`到货单编号 ${req.arrId} 已用于内容不同的单据，拒绝提交`);
1011	      return {
1012	        duplicate: true,
1013	        header: this.arrivalHeader(req.arrId, existed),
1014	        lines: existed.resultLines,
1015	        repeatedFrom: this.repeatedArrivalSource(req.arrId),
1016	      };
1017	    }
1018	    // 与入库/出库/调拨/盘点/冲销单共用唯一编号空间（采购单编号空间独立，不在此列）
1019	    if (this.docs[req.arrId] !== undefined)
1020	      throw new BizError(`单据编号 ${req.arrId} 已用于入库/出库/调拨/盘点单，拒绝提交`);
1021	    if (this.revs[req.arrId] !== undefined)
1022	      throw new BizError(`单据编号 ${req.arrId} 已用于冲销单，拒绝提交`);
1023	
1024	    const po = this.pos[req.poId];
1025	    if (po === undefined) throw new BizError(`采购单 ${req.poId} 不存在，拒绝到货`);
1026	
1027	    for (const [pid] of req.items) {
1028	      if (this.base.products[pid] === undefined) throw new BizError(`商品未登记，拒绝整单：${pid}`);
1029	      if (po.ordered[pid] === undefined)
1030	        throw new BizError(`商品 ${pid} 不在采购单 ${req.poId} 的订购明细内，拒绝整单`);
1031	    }
1032	
1033	    const arrivedBefore = this.effectiveArrived(req.poId); // 未冲销累计到货
1034	    const pids = [...req.items.keys()].sort();
1035	    const wh = po.wh;
1036	
1037	    // 超收与溢出先整单校验、模拟，任一商品失败则不登记任何到货
1038	    const reportLines: string[] = [];
1039	    const planned = new Map<string, { before: number; after: number; qty: number }>();
1040	
1041	    for (const pid of pids) {
1042	      const qty = req.items.get(pid)!;
1043	      const cumulative = (arrivedBefore[pid] ?? 0) + qty; // 含本次的未冲销累计到货
1044	      if (cumulative > po.ordered[pid])
1045	        throw new BizError(
1046	          `商品 ${pid} 到货超收：订购 ${po.ordered[pid]}，此前未冲销累计到货 ${arrivedBefore[pid] ?? 0}，本次 ${qty}，拒绝整单`,
1047	        );
1048	      const before = getStock(this.draft, pid, wh);
1049	      const after = before + qty;
1050	      if (after > MAX_SAFE)
1051	        throw new BizError(`商品 ${pid} 到货并入仓库 ${wh} 后余量超出安全整数范围，拒绝整单`);
1052	      planned.set(pid, { before, after, qty });
1053	    }
1054	
1055	    const qtyRecord: Record<string, number> = nullProto();
1056	    for (const pid of pids) {
1057	      const { before, after, qty } = planned.get(pid)!;
1058	      setStock(this.draft, pid, wh, after);
1059	      this.additions.push({
1060	        seq: ++this.seq, doc: req.arrId, type: 'arrival', product: pid, wh,
1061	        qty, before, after, po: req.poId,
1062	      });
1063	      const cumulative = (arrivedBefore[pid] ?? 0) + qty;
1064	      const remaining = po.ordered[pid] - cumulative;
1065	      qtyRecord[pid] = qty;
1066	      reportLines.push(
1067	        `到货 ${pid} @${wh} +${qty}：库存 ${before} -> ${after}；累计到货 ${cumulative}/${po.ordered[pid]}，待到货 ${remaining}`,
1068	      );
1069	    }
1070	
1071	    this.arrivals[req.arrId] = { poId: req.poId, wh, qty: qtyRecord, resultLines: reportLines };
1072	    this.newArrivalIds.push(req.arrId);
1073	
1074	    return { duplicate: false, header: this.arrivalHeader(req.arrId, this.arrivals[req.arrId]), lines: reportLines };
1075	  }
1076	
1077	  private arrivalHeader(arrId: string, rec: ArrivalRecord): string {
1078	    return `到货单 ${arrId} 提交成功，采购单 ${rec.poId}，收货仓 ${rec.wh}，共 ${Object.keys(rec.qty).length} 种商品：`;
1079	  }
1080	
1081	  private repeatedRevSource(revId: string): 'store' | 'batch' {
1082	    return this.base.reversals[revId] !== undefined ? 'store' : 'batch';
1083	  }
1084	
1085	  private repeatedDocSource(docId: string): 'store' | 'batch' {
1086	    return this.base.docs[docId] !== undefined ? 'store' : 'batch';
1087	  }
1088	
1089	  /** 整单先校验、模拟，全部合法后才登记到草稿；任一明细失败则整批保持原状。 */
1090	  applyDoc(req: DocRequest): ApplyOutcome {
1091	    const content = canonicalContent(req);
1092	    const existed = this.docs[req.docId];
1093	    if (existed !== undefined) {
1094	      if (stableStringify(existed.content) !== stableStringify(content))
1095	        throw new BizError(`单据编号 ${req.docId} 已用于业务内容不同的单据，拒绝提交`);
1096	      return { duplicate: true, header: this.docHeader(req.docId, existed), lines: existed.resultLines, repeatedFrom: this.repeatedDocSource(req.docId) };
1097	    }
1098	    // 编号空间与出库/入库/调拨/盘点/到货/冲销单共用
1099	    if (this.revs[req.docId] !== undefined)
1100	      throw new BizError(`单据编号 ${req.docId} 已用于冲销单，拒绝提交`);
1101	    if (this.arrivals[req.docId] !== undefined)
1102	      throw new BizError(`单据编号 ${req.docId} 已用于到货单，拒绝提交`);
1103	
1104	    for (const pid of req.items.keys()) {
1105	      if (this.base.products[pid] === undefined) throw new BizError(`商品未登记，拒绝整单：${pid}`);
1106	    }
1107	
1108	    const reportLines: string[] = [];
1109	    const typeLabel = req.type === 'in' ? '入库' : req.type === 'out' ? '出库' : '调拨';
1110	
1111	    for (const pid of [...req.items.keys()].sort()) {
1112	      const qty = req.items.get(pid)!;
1113	
1114	      if (req.type === 'in') {
1115	        const wh = req.wh!;
1116	        const before = getStock(this.draft, pid, wh);
1117	        const after = before + qty;
1118	        if (after > MAX_SAFE) throw new BizError(`商品 ${pid} 入库后余量超出安全整数范围，拒绝整单`);
1119	        setStock(this.draft, pid, wh, after);
1120	        this.additions.push({ seq: ++this.seq, doc: req.docId, type: 'in', product: pid, wh, qty, before, after });
1121	        reportLines.push(`入库 ${pid} @${wh} +${qty}：${before} -> ${after}`);
1122	      } else if (req.type === 'out') {
1123	        const wh = req.wh!;
1124	        const before = getStock(this.draft, pid, wh);
1125	        if (before < qty)
1126	          throw new BizError(`商品 ${pid} 仓库 ${wh} 余量不足（当前 ${before}，需出库 ${qty}），拒绝整单`);
1127	        const after = before - qty;
1128	        setStock(this.draft, pid, wh, after);
1129	        this.additions.push({ seq: ++this.seq, doc: req.docId, type: 'out', product: pid, wh, qty, before, after });
1130	        reportLines.push(`出库 ${pid} @${wh} -${qty}：${before} -> ${after}`);
1131	      } else {
1132	        const from = req.from!;
1133	        const to = req.to!;
1134	        const beforeFrom = getStock(this.draft, pid, from);
1135	        if (beforeFrom < qty)
1136	          throw new BizError(`商品 ${pid} 调出仓 ${from} 余量不足（当前 ${beforeFrom}，需调拨 ${qty}），拒绝整单`);
1137	        const afterFrom = beforeFrom - qty;
1138	        const beforeTo = getStock(this.draft, pid, to);
1139	        const afterTo = beforeTo + qty;
1140	        if (afterTo > MAX_SAFE) throw new BizError(`商品 ${pid} 调入后余量超出安全整数范围，拒绝整单`);
1141	        setStock(this.draft, pid, from, afterFrom);
1142	        setStock(this.draft, pid, to, afterTo);
1143	        this.additions.push({
1144	          seq: ++this.seq, doc: req.docId, type: 'transfer', product: pid, wh: from,
1145	          qty, before: beforeFrom, after: afterFrom, from, to,
1146	        });
1147	        this.additions.push({
1148	          seq: ++this.seq, doc: req.docId, type: 'transfer', product: pid, wh: to,
1149	          qty, before: beforeTo, after: afterTo, from, to,
1150	        });
1151	        reportLines.push(
1152	          `调拨 ${pid} ${from} -> ${to} ${qty}：${from} ${beforeFrom}->${afterFrom}；${to} ${beforeTo}->${afterTo}`,
1153	        );
1154	      }
1155	    }
1156	
1157	    // 全部明细合法：登记到模拟视图；真正落库由 commit 统一完成
1158	    this.docs[req.docId] = { content, resultLines: reportLines };
1159	    this.newDocIds.push(req.docId);
1160	
1161	    const header = `${typeLabel}单 ${req.docId} 提交成功，共 ${req.items.size} 种商品：`;
1162	    return { duplicate: false, header, lines: reportLines };
1163	  }
1164	
1165	  /**
1166	   * 整单盘点校正：首次提交先逐项核对当前（草稿）余量与预期账面量，任一不符整单拒绝
1167	   * 并说明冲突商品及当前量；全部相符才把列出的商品校正为实盘量（差额 = 实盘 - 账面，
1168	   * 可增、可减、可为零），未列出的商品及其他仓库不变。同编号同内容重放只返回原
1169	   * 结果，即使余量改变或盘点已冲销也不再核对、不再生效。
1170	   */
1171	  applyCount(req: CountRequest): ApplyOutcome {
1172	    const content = canonicalCountContent(req);
