1534	function formatEntry(e: LedgerEntry): string {
1535	  let line: string;
1536	  if (e.type === 'count' || e.type === 'count-rev') {
1537	    const applied = e.type === 'count' ? e.diff! : -e.diff!; // 冲销盘点应用反向差额
1538	    line =
1539	      `#${e.seq}\t单据=${e.doc}\t${TYPE_LABEL[e.type]}\t商品=${e.product}\t仓库=${e.wh}` +
1540	      `\t差额=${fmtSigned(applied)}\t${e.before}->${e.after}\t账面=${e.expected}\t实盘=${e.actual}`;
1541	  } else {
1542	    let signed: string;
1543	    // 符号必须与前后余量一致：入库/冲销出库/到货/调入方向为增，其余为减
1544	    const increases =
1545	      e.type === 'in' || e.type === 'out-rev' || e.type === 'arrival' ||
1546	      ((e.type === 'transfer' || e.type === 'transfer-rev') &&
1547	        (e.type === 'transfer') === (e.wh === e.to));
1548	    signed = `${increases ? '+' : '-'}${e.qty}`;
