1759	  const store = loadStore(dataDir);
1760	  const ledger = new Ledger(store);
1761	  // 模拟阶段收集输出：只有整批通过并完成保存后才向用户报告，绝不报告部分成功
1762	  const blocks: string[] = [];
1763	  let newCount = 0;
1764	
1765	  requests.forEach((r, i) => {
1766	    const pos = `第 ${i + 1}/${requests.length} 项`;
1767	    // 模拟阶段的业务拒绝同样标注列表位置与原因
1768	    const apply = (): ApplyOutcome => {
1769	      switch (r.kind) {
1770	        case 'doc': return ledger.applyDoc(r.req);
1771	        case 'count': return ledger.applyCount(r.req);
1772	        case 'reverse': return ledger.applyReversal(r.docId, r.orig);
1773	        case 'po': return ledger.applyPurchase(r.req);
1774	        case 'arrival': return ledger.applyArrival(r.req);
1775	      }
1776	    };
1777	    let outcome: ApplyOutcome;
1778	    try {
1779	      outcome = apply();
1780	    } catch (e) {
1781	      if (e instanceof BizError) throw new BizError(`第 ${i + 1} 项：${e.message}`);
1782	      throw e;
1783	    }
1784	    const id =
1785	      r.kind === 'reverse' ? r.docId
1786	      : r.kind === 'po' ? r.req.poId
1787	      : r.kind === 'arrival' ? r.req.arrId
1788	      : r.req.docId;
1789	
1790	    let status: string;
1791	    if (outcome.duplicate) {
1792	      const where = outcome.repeatedFrom === 'batch' ? '（本批此前已出现）' : '（导入前已存在）';
1793	      status = `重复${where}，返回原提交结果，不重新核对库存、不追加流水`;
1794	    } else {
1795	      status = '首次生效';
1796	      newCount++;
1797	    }
1798	    blocks.push([`[${pos}] 单据 ${id}：${status}`, outcome.header, ...outcome.lines].join('\n'));
1799	  });
1800	
1801	  // 全部项通过：有新生效单据时整批一次性保存；全部重复则不改写数据
1802	  ledger.commit(dataDir);
1803	
1804	  console.log(`整批导入完成：共 ${requests.length} 项，首次生效 ${newCount} 项，重复 ${requests.length - newCount} 项。`);
1805	  for (const block of blocks) console.log(block);
1806	}
