```ts
applyCancel(req: CancelRequest): ApplyOutcome {
  const existed = this.cancels[req.cancelId];
  if (existed !== undefined) {
    if (existed.poId !== req.poId || stableStringify(existed.qty) !== stableStringify(canonicalArrivalItems(req.items)))
      throw new BizError(`取消单编号 ${req.cancelId} 已用于内容不同的单据，拒绝提交`);
    return { duplicate: true, header: this.cancelHeader(req.cancelId, existed), lines: existed.resultLines, repeatedFrom: this.repeatedCancelSource(req.cancelId) };
  }
  if (this.docs[req.cancelId] !== undefined) throw ...;
  if (this.revs[req.cancelId] !== undefined) throw ...;
  if (this.arrivals[req.cancelId] !== undefined) throw ...;
  const po = this.pos[req.poId];
  if (po === undefined) throw new BizError(`采购单 ${req.poId} 不存在，拒绝取消`);
  for (const pid of req.items.keys()) {
    if (po.ordered[pid] === undefined) throw new BizError(`商品 ${pid} 不在采购单 ${req.poId} 的订购明细内，拒绝整单`);
  }
  const arrived = this.effectiveArrived(req.poId);
  const cancelled = this.effectiveCancelled(req.poId);
  const pids = [...req.items.keys()].sort();
  // 整单校验
  for (const pid of pids) {
    const qty = req.items.get(pid)!;
    const pending = po.ordered[pid] - (arrived[pid] ?? 0) - (cancelled[pid] ?? 0);
    if (qty > pending)
      throw new BizError(`商品 ${pid} 取消量超出待到货量：订购 ${po.ordered[pid]}，有效到货 ${arrived[pid]??0}，有效取消 ${cancelled[pid]??0}，待到货 ${pending}，本次取消 ${qty}，拒绝整单`);
  }
  const qtyRecord = nullProto; lines...
  for pid: effAfter = (cancelled[pid]??0)+qty; pendingAfter = ordered - (arrived??0) - effAfter;
    line: `取消 ${pid} x${qty}：有效取消 ${effAfter}，待到货 ${pendingAfter}`
  this.cancels[req.cancelId] = { poId, qty: qtyRecord, resultLines };
  this.newCancelIds.push(...);
  return {duplicate:false, header: cancelHeader, lines};
}
```

