applyCancelReversal:

```ts
private applyCancelReversal(revId, origId, origCancel: CancelRecord): ApplyOutcome {
  if (this.reversedOrigs.has(origId)) { ...throw 已被冲销单 X 成功冲销... }
  const poId = origCancel.poId;
  const po = this.pos[poId];
  const arrived = this.effectiveArrived(poId);
  const cancelled = this.effectiveCancelled(poId); // 含本取消单（尚未冲销）
  const pids = Object.keys(origCancel.qty).sort();
  const reportLines = [];
  for (const pid of pids) {
    const qty = origCancel.qty[pid];
    const effAfter = (cancelled[pid] ?? 0) - qty;
    const pendingAfter = po.ordered[pid] - (arrived[pid] ?? 0) - effAfter;
    reportLines.push(`冲销取消 原单=${origId} 采购单=${poId} 商品=${pid} 本次=${qty}：有效取消降至 ${effAfter}，待到货 ${pendingAfter}`);
  }
  this.revs[revId] = { orig: origId, resultLines: reportLines };
  this.newRevIds.push(revId);
  this.reversedOrigs.add(origId);
  return { duplicate:false, header: `冲销单 ${revId} 提交成功，冲销取消原单 ${origId}（采购单 ${poId}），共 ${pids.length} 种商品：`, lines: reportLines };
}
```

No stock checks needed (no stock impact) — cancel reversal always succeeds if not already reversed. 

