  const origDoc = store.docs[rev.orig];
  if (origDoc !== undefined) expected = `${origDoc.content.type}-rev` as EntryType;
  else expected = 'arrival-rev'; // 原单为到货单（前面已确认必为库存单、到货单或取消单之一）
  for (const e of store.entries) {
