for (const revId of Object.keys(store.reversals)) {
  if (store.cancels[store.reversals[revId].orig] !== undefined) continue; // 冲销取消无流水
  if (revIdsWithEntries[revId] !== true) throw bad(`冲销单 ${revId} 缺少冲销流水`);
