  const arr = this.arrivals[rec.orig];
  const n = Object.keys(arr.qty).length;
  return `冲销单 ${revId} 提交成功，冲销到货原单 ${rec.orig}（采购单 ${arr.poId}），共 ${n} 种商品：`;
}

